using System.Runtime.InteropServices;
using GlassDock.TopBar;
int count=0;
void Check(bool condition,string message){if(!condition)throw new Exception(message);count++;}
Check(Marshal.SizeOf<BarNative.Input>()==(IntPtr.Size==8?40:28),"SendInput ABI size differs from Windows INPUT");
Check(Marshal.OffsetOf<BarNative.Input>(nameof(BarNative.Input.Data)).ToInt32()==(IntPtr.Size==8?8:4),"INPUT union alignment differs from Win32");
Check(Marshal.SizeOf<BarNative.AppBarData>()==(IntPtr.Size==8?48:36),"APPBARDATA ABI mismatch");
Check(StatusText.Keyboard(unchecked((long)0xFFFFFFFFF0000412UL))=="한국어","HKL upper bits should not affect Korean keyboard label");
Check(StatusText.Keyboard(0x0409)=="ENG","English keyboard label");
Check(StatusText.Keyboard(0)=="언어","Unknown keyboard must not appear as English");
Check(StatusText.Battery(.52f,false)=="▰ 52%","Battery percentage");
Check(StatusText.Battery(0,false)=="▰ 0%","Empty battery is still a real battery");
Check(StatusText.Battery(1,false)=="▰ 100%","Full battery");
Check(StatusText.Battery(.5f,true)==null,"No battery hardware should not show a fake battery");
Check(StatusText.Battery(255,false)==null,"Unknown battery reading must not be clamped to 100%");
Check(StatusText.Battery(float.NaN,false)==null,"NaN battery state");
Check(StatusText.Battery(-1,false)==null,"Negative battery state");
foreach(var entry in new[]{(Dpi:0u,Height:28),(Dpi:96u,Height:28),(Dpi:120u,Height:35),(Dpi:144u,Height:42),(Dpi:192u,Height:56)})Check(StatusText.HeightForDpi(entry.Dpi)==entry.Height,"DPI reserved height");
var now=new DateTime(2026,11,5,19,8,0);
Check(StatusText.Clock(now,false)=="11월 5일 (목) 오후 7:08","Clock should show real date, weekday and local time");
Check(StatusText.Clock(now,true)=="오후 7:08","Compact clock");
Check(BarBackground.OpacityFor(false,false)==0,"Desktop background must be fully transparent");
Check(BarBackground.OpacityFor(true,false)==0,"Restored windows must leave no background band");
Check(BarBackground.OpacityFor(true,true)==1.0,"Maximized/fullscreen windows must completely hide the wallpaper");
var screen=new BarNative.Rect {Left=-1920,Top=0,Right=0,Bottom=1080};
Check(BarBackground.CoversScreen(screen,screen),"Fullscreen on a monitor with negative coordinates");
Check(BarBackground.CoversScreen(new BarNative.Rect {Left=-1928,Top=-8,Right=8,Bottom=1088},screen),"Window frame overhang still covers monitor");
Check(!BarBackground.CoversScreen(new BarNative.Rect {Left=-1920,Top=28,Right=0,Bottom=1080},screen),"A work-area window needs IsZoomed, not fullscreen geometry");
Check(!BarBackground.CoversScreen(new BarNative.Rect {Left=-1920,Top=0,Right=-960,Bottom=1080},screen),"Snapped half-screen window is not fullscreen");
Check(!BarBackground.CoversScreen(new BarNative.Rect {Left=0,Top=0,Right=1920,Bottom=1080},screen),"Fullscreen on another monitor must not affect this bar");
var trayArea=new BarNative.Rect {Left=0,Top=28,Right=1920,Bottom=1040};
var trayPosition=TrayPopupPlacement.Below(new BarNative.Rect {Left=1700,Top=0,Right=1734,Bottom=28},trayArea,234,74,4);
Check(trayPosition.X==1600&&trayPosition.Y==32,"Native tray should align below the arrow in physical pixels");
trayPosition=TrayPopupPlacement.Below(new BarNative.Rect {Left=1900,Top=0,Right=1920,Bottom=28},trayArea,234,74,4);
Check(trayPosition.X==1686&&trayPosition.Y==32,"Tray must stay inside the right monitor edge");
trayPosition=TrayPopupPlacement.Below(new BarNative.Rect {Left=-1920,Top=0,Right=-1886,Bottom=28},new BarNative.Rect {Left=-1920,Top=28,Right=0,Bottom=1040},234,74,4);
Check(trayPosition.X==-1920&&trayPosition.Y==32,"Tray must clamp correctly on a monitor with negative coordinates");
trayPosition=TrayPopupPlacement.Below(new BarNative.Rect {Left=3400,Top=0,Right=3468,Bottom=56},new BarNative.Rect {Left=0,Top=56,Right=3840,Bottom=2080},468,148,8);
Check(trayPosition.X==3200&&trayPosition.Y==64,"200 percent DPI must not double-scale physical tray coordinates");
trayPosition=TrayPopupPlacement.Below(new BarNative.Rect {Left=20,Top=0,Right=54,Bottom=28},new BarNative.Rect {Left=0,Top=28,Right=100,Bottom=80},234,200,4);
Check(trayPosition.X==0&&trayPosition.Y==28,"Oversized flyout must not produce invalid clamp bounds");
Check(NotificationPlacement.IsWindowsToast("ShellExperienceHost","Windows.UI.Core.CoreWindow","새 알림"),"Korean Windows toast host must be recognized");
Check(NotificationPlacement.IsWindowsToast("shellhost","Windows.UI.Core.CoreWindow","New notification"),"English toast host name comparison must ignore process casing");
Check(!NotificationPlacement.IsWindowsToast("KakaoTalk","Windows.UI.Core.CoreWindow","새 알림"),"Custom app windows must never be moved as system toasts");
Check(!NotificationPlacement.IsWindowsToast("ShellExperienceHost","Windows.UI.Core.CoreWindow","알림 센터"),"Notification center must not be confused with a banner");
Check(!NotificationPlacement.IsWindowsToast("ShellExperienceHost","OtherWindow","새 알림"),"Only the native toast class may be relocated");
var banner=NotificationPlacement.BelowBar(new BarNative.Rect {Left=0,Top=0,Right=1920,Bottom=28},trayArea,400,180,8);
Check(banner.X==1512&&banner.Y==36,"Notification banner must appear below the right side of the bar");
banner=NotificationPlacement.BelowBar(new BarNative.Rect {Left=-1920,Top=0,Right=0,Bottom=28},new BarNative.Rect {Left=-1920,Top=28,Right=0,Bottom=1040},400,180,8);
Check(banner.X==-408&&banner.Y==36,"Notification placement must support secondary monitors left of the primary");
banner=NotificationPlacement.BelowBar(new BarNative.Rect {Left=0,Top=0,Right=3840,Bottom=56},new BarNative.Rect {Left=0,Top=56,Right=3840,Bottom=2080},800,360,16);
Check(banner.X==3024&&banner.Y==72,"High DPI notification offsets must use physical pixels once");
if(OperatingSystem.IsWindows())
{
    var opacity=BarBackground.GetOpacity(new BarNative.Rect {Left=0,Top=0,Right=1920,Bottom=1080});
    Check(opacity==0||opacity==1.0,"Live Win32 window enumeration returned an invalid opacity");
    Console.WriteLine($"Live primary-screen background opacity: {opacity:P0}");
}
Console.WriteLine($"PASS {count} top bar status and Win32 ABI checks");
